package com.khateev.hermi.shared.ai

import android.content.Context
import android.util.Log
import com.khateev.hermi.shared.interfaces.RecognitionManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONArray
import org.json.JSONObject
import org.vosk.Model
import org.vosk.Recognizer
import java.io.File
import java.io.FileOutputStream

/**
 * Offline speech recognition.
 *
 * By default the decoder is constrained to the command phrase bank
 * (`grammar_phrases.txt`, generated by tools/generate_command_catalog.py) instead
 * of the open vocabulary. The car understands ~100 commands, so there is no
 * reason to let the recognizer produce "check while level" — measured on the
 * accent stand, grammar decoding lifts command recognition from 71% to 98% on
 * hard accents. Pass `useGrammar = false` for open-vocabulary decoding.
 *
 * No audio conditioning in front: a 110 Hz high-pass and AGC were measured on the
 * accent stand and moved nothing (road noise is harmless even at SNR 0 dB, and
 * Vosk normalizes levels itself), so the raw capture goes straight in.
 */
class VoskManager(
    private val context: Context,
    private val useGrammar: Boolean = true
) : RecognitionManager {

    private var model: Model? = null
    private var recognizer: Recognizer? = null
    private var grammar: String? = null

    companion object {
        private const val TAG = "VoskManager"
        private const val SAMPLE_RATE = 16000f
        private const val MODEL_NAME = "vosk-model-small-en-us-0.15"
        private const val GRAMMAR_ASSET = "grammar_phrases.txt"

        /** Vosk emits this for audio that does not fit the grammar. */
        private const val UNKNOWN_TOKEN = "[unk]"
    }

    override suspend fun initialize(): Boolean = withContext(Dispatchers.IO) {
        try {
            Log.d(TAG, "Initializing Vosk...")

            val modelDir = getModelDirectory()

            Log.d(TAG, "Loading model from: ${modelDir.absolutePath}")
            model = Model(modelDir.absolutePath)
            grammar = if (useGrammar) loadGrammar() else null
            recognizer = newRecognizer()

            Log.d(TAG, "Vosk initialized successfully (grammar=${grammar != null})")
            true
        } catch (e: Exception) {
            Log.e(TAG, "Failed to initialize Vosk", e)
            false
        }
    }

    /** Grammar-constrained recognizer, falling back to open vocabulary. */
    private fun newRecognizer(): Recognizer {
        val json = grammar
        if (json != null) {
            try {
                return Recognizer(model, SAMPLE_RATE, json)
            } catch (e: Exception) {
                Log.e(TAG, "Grammar rejected by Vosk, falling back to open vocabulary", e)
                grammar = null
            }
        }
        return Recognizer(model, SAMPLE_RATE)
    }

    private fun loadGrammar(): String? = try {
        val phrases = context.assets.open(GRAMMAR_ASSET).bufferedReader().useLines { lines ->
            lines.map { it.trim() }.filter { it.isNotEmpty() }.toList()
        }
        Log.d(TAG, "Grammar: ${phrases.size} phrases")
        JSONArray().apply {
            phrases.forEach { put(it) }
            put(UNKNOWN_TOKEN)
        }.toString()
    } catch (e: Exception) {
        Log.e(TAG, "No decoding grammar available, using open vocabulary", e)
        null
    }

    override fun acceptChunk(audioData: FloatArray): Boolean {
        val rec = recognizer ?: return false
        val shortData = ShortArray(audioData.size) {
            (audioData[it] * 32767f).toInt().coerceIn(-32768, 32767).toShort()
        }
        return rec.acceptWaveForm(shortData, shortData.size)
    }

    override fun recognizeAudio(audioData: FloatArray): String? {
        val rec = recognizer ?: return null

        return try {
            val shortData = ShortArray(audioData.size) {
                (audioData[it] * 32767f).toInt().coerceIn(-32768, 32767).toShort()
            }

            if (rec.acceptWaveForm(shortData, shortData.size)) {
                parseResult(rec.result)
            } else {
                parseResult(rec.finalResult)
            }
        } catch (e: Exception) {
            Log.e(TAG, "Recognition error", e)
            null
        }
    }

    override fun release() {
        recognizer?.close()
        model?.close()
        recognizer = null
        model = null
        Log.d(TAG, "Vosk released")
    }

    private fun getModelDirectory(): File {
        val modelDir = File(context.filesDir, MODEL_NAME)

        if (!modelDir.exists()) {
            Log.d(TAG, "Copying model from assets...")
            copyModelFromAssets(modelDir)
        }

        return modelDir
    }

    private fun copyModelFromAssets(modelDir: File) {
        try {
            val assetPath = "models/$MODEL_NAME"

            copyAssetFolder(assetPath, modelDir)

            Log.d(TAG, "Model copied")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to copy model", e)
            throw IllegalStateException(
                "Model files missing."
            )
        }
    }

    private fun copyAssetFolder(assetPath: String, targetDir: File) {
        targetDir.mkdirs()

        val files = context.assets.list(assetPath) ?: emptyArray()

        if (files.isEmpty()) {
            Log.d(TAG, "Copying file: $assetPath")
            context.assets.open(assetPath).use { input ->
                FileOutputStream(targetDir).use { output ->
                    input.copyTo(output)
                }
            }
        } else {
            files.forEach { fileName ->
                val assetFilePath = "$assetPath/$fileName"
                val targetFile = File(targetDir, fileName)

                val subFiles = context.assets.list(assetFilePath) ?: emptyArray()

                if (subFiles.isEmpty()) {
                    Log.d(TAG, "Copying: $fileName")
                    context.assets.open(assetFilePath).use { input ->
                        FileOutputStream(targetFile).use { output ->
                            input.copyTo(output)
                        }
                    }
                } else {
                    Log.d(TAG, "Copying folder: $fileName")
                    copyAssetFolder(assetFilePath, targetFile)
                }
            }
        }
    }


    /**
     * Result text with Vosk's `[unk]` fillers removed. Audio the grammar cannot
     * explain comes back as those tokens; feeding them to the classifier would
     * be feeding it noise, so a result that is nothing but fillers becomes empty
     * and the app reports that it did not catch the command.
     */
    private fun parseResult(json: String): String {
        return try {
            val text = JSONObject(json).optString("text", "")
            text.split(" ")
                .filter { it.isNotBlank() && it != UNKNOWN_TOKEN }
                .joinToString(" ")
        } catch (e: Exception) {
            ""
        }
    }
}